  "prediction_basis_card_ids": ["C01","C11","C04","C17","C18","C53","C56"],
  "claims": [
    {
      "claim": "Safinamide, the closest structural context with a basic benzylamine, fluorophenyl, and amide motif, has absolute oral bioavailability of about 95% in fasted and fed humans after a 50 mg IR tablet versus IV; L2 records C17 and C18 are consistent.",
      "card_ids": ["C01","C11","C04","C17","C18"]
    },
    {
      "claim": "All other transferable human L1 contexts report F values or qualitative outcomes at or above about 50%: aprepitant 59-67%, tegoprazan 86-100%, rolipram 73%, balcinrenone 52%, d-fenfluramine 61-69%, SB-681323 about 50%, thalidomide 80-100%, and INS018_055 good oral bioavailability.",
      "card_ids": ["C03","C07","C10","C12","C21","C08","C05","C15","C13","C06","C02","C14","C09"]
    },
    {
      "claim": "L2 animal low-F records for rolipram in rabbit (3-4%) and rhesus monkey (<0.1%) are species-specific and do not transfer to the human-oriented prediction.",
      "card_ids": ["C16","C19"]
    },
    {
      "claim": "L3 oral AUC/Cmax records show measurable human oral exposure for reference molecules M01 and M03 and for a metabolite of M02, but none includes an IV comparator or an absolute F value; they do not alter the high direction.",
      "card_ids": ["C22","C23","C24","C25","C26","C27","C28","C29","C30","C31","C32","C33"]
    },
    {
      "claim": "L4 solubility records are for reference molecules M01-M04 in lipid formulations or buffers; they are not query-specific permeability or absorption measurements. C37 and C39 are weakly consistent with favorable solubility for ionizable basic compounds, but do not change the prediction.",
      "card_ids": ["C34","C35","C36","C37","C38","C39","C40","C41","C42","C43","C44","C45"]
    },
    {
      "claim": "L5 Caco-2 records for structurally similar fused-lactam basic amines M01 and M03 show high permeability (>10 x 10^-6 cm/s) and low efflux ratios (2.27 and 1.75), indicating no gut-wall efflux barrier; C55 similarly shows efflux ratio <2 for fexuprazan. These support high absorption but are not query-specific.",
      "card_ids": ["C53","C56","C55"]
    },
    {
      "claim": "Other L5 records concern repotrectinib (ABCB1 substrate), tramadol (not a P-gp substrate), and P57 (MRP/P-gp substrate); these are not structurally aligned with the query and do not change the prediction.",
      "card_ids": ["C46","C50","C51","C54","C57"]
    },
    {
      "claim": "No affirmative transferable F<20% evidence exists; the prediction remains high.",
      "card_ids": ["C01","C11","C04","C17","C18","C53","C56"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C53","C56","C55"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the supplied records.",
    "No exact same-scaffold reference context is present; the closest structural contexts are safinamide and L5 reference molecules M01/M03, but the query's fused indole-lactam differs from safinamide's simple benzylamine amide.",
    "No query-specific Caco-2 permeability, efflux, or intestinal metabolism data are supplied; L5 records are for reference molecules.",
    "No query-specific first-pass metabolism or clearance data are supplied; L2 animal low-F records are species-specific.",
    "Dose, formulation, and prandial-state effects for the query are unknown.",
    "L3/L4 records lack IV comparators and query-specific measurements, so they cannot quantify absolute F."
  ],
  "decision_summary": "L5 gut-wall efflux records for structurally similar fused-lactam basic amines (M01/M03) show high Caco-2 permeability and low efflux, supporting high absorption and no gut-wall efflux barrier; no query-specific or transferable F<20% evidence exists. All transferable human L1/L2 F values are >=50%, with the closest structural context (safinamide) at about 95%, so the prediction remains high."
}

